 if (uGain <= 0.0001) discard; // Zero-intensity effects must not write HDR pixels.
vec2 p=abs(vUv-.5)*2.;float a=exp(-p.x*p.x*7.)*(1.-smoothstep(.35,1.,p.y))*vLive;
